"""B-tree implementation supporting insert, delete, search, and range_query."""


class BTreeNode:
    __slots__ = ("keys", "children", "leaf")

    def __init__(self, leaf: bool = False):
        self.keys: list = []
        self.children: list["BTreeNode"] = []
        self.leaf = leaf


class BTree:
    def __init__(self, t: int = 3):
        if t < 2:
            raise ValueError("Minimum degree t must be >= 2")
        self.t = t  # minimum degree
        self.root = BTreeNode(leaf=True)

    # ── Search ──────────────────────────────────────────────────────

    def search(self, key) -> tuple[BTreeNode | None, int]:
        """Return (node, index) where key is found, or (None, -1)."""
        return self._search(self.root, key)

    def _search(self, node: BTreeNode, key) -> tuple[BTreeNode | None, int]:
        i = 0
        while i < len(node.keys) and key > node.keys[i]:
            i += 1
        if i < len(node.keys) and key == node.keys[i]:
            return (node, i)
        if node.leaf:
            return (None, -1)
        return self._search(node.children[i], key)

    # ── Insert ──────────────────────────────────────────────────────

    def insert(self, key):
        root = self.root
        if len(root.keys) == 2 * self.t - 1:
            new_root = BTreeNode()
            new_root.children.append(self.root)
            self._split_child(new_root, 0)
            self.root = new_root
        self._insert_non_full(self.root, key)

    def _insert_non_full(self, node: BTreeNode, key):
        i = len(node.keys) - 1
        if node.leaf:
            node.keys.append(None)
            while i >= 0 and key < node.keys[i]:
                node.keys[i + 1] = node.keys[i]
                i -= 1
            node.keys[i + 1] = key
        else:
            while i >= 0 and key < node.keys[i]:
                i -= 1
            i += 1
            if len(node.children[i].keys) == 2 * self.t - 1:
                self._split_child(node, i)
                if key > node.keys[i]:
                    i += 1
            self._insert_non_full(node.children[i], key)

    def _split_child(self, parent: BTreeNode, i: int):
        t = self.t
        full = parent.children[i]
        new_node = BTreeNode(leaf=full.leaf)

        parent.children.insert(i + 1, new_node)
        parent.keys.insert(i, full.keys[t - 1])

        new_node.keys = full.keys[t:]
        full.keys = full.keys[: t - 1]

        if not full.leaf:
            new_node.children = full.children[t:]
            full.children = full.children[:t]

    # ── Delete ──────────────────────────────────────────────────────

    def delete(self, key):
        self._delete(self.root, key)
        if not self.root.keys and not self.root.leaf:
            self.root = self.root.children[0]

    def _delete(self, node: BTreeNode, key):
        t = self.t
        i = 0
        while i < len(node.keys) and key > node.keys[i]:
            i += 1

        if i < len(node.keys) and key == node.keys[i]:
            if node.leaf:
                node.keys.pop(i)
            else:
                self._delete_internal(node, i)
        elif node.leaf:
            return  # key not found
        else:
            if len(node.children[i].keys) < t:
                self._fill(node, i)
            # After fill, the child that should contain key may have moved
            if i > len(node.keys):
                self._delete(node.children[i - 1], key)
            else:
                self._delete(node.children[i], key)

    def _delete_internal(self, node: BTreeNode, i: int):
        t = self.t
        key = node.keys[i]

        if len(node.children[i].keys) >= t:
            pred = self._max_key(node.children[i])
            node.keys[i] = pred
            self._delete(node.children[i], pred)
        elif len(node.children[i + 1].keys) >= t:
            succ = self._min_key(node.children[i + 1])
            node.keys[i] = succ
            self._delete(node.children[i + 1], succ)
        else:
            self._merge(node, i)
            self._delete(node.children[i], key)

    def _min_key(self, node: BTreeNode):
        while not node.leaf:
            node = node.children[0]
        return node.keys[0]

    def _max_key(self, node: BTreeNode):
        while not node.leaf:
            node = node.children[-1]
        return node.keys[-1]

    def _fill(self, node: BTreeNode, i: int):
        t = self.t
        if i > 0 and len(node.children[i - 1].keys) >= t:
            self._borrow_prev(node, i)
        elif i < len(node.children) - 1 and len(node.children[i + 1].keys) >= t:
            self._borrow_next(node, i)
        else:
            if i < len(node.children) - 1:
                self._merge(node, i)
            else:
                self._merge(node, i - 1)

    def _borrow_prev(self, node: BTreeNode, i: int):
        child = node.children[i]
        sibling = node.children[i - 1]

        child.keys.insert(0, node.keys[i - 1])
        if not child.leaf:
            child.children.insert(0, sibling.children.pop())

        node.keys[i - 1] = sibling.keys.pop()

    def _borrow_next(self, node: BTreeNode, i: int):
        child = node.children[i]
        sibling = node.children[i + 1]

        child.keys.append(node.keys[i])
        if not child.leaf:
            child.children.append(sibling.children.pop(0))

        node.keys[i] = sibling.keys.pop(0)

    def _merge(self, node: BTreeNode, i: int):
        child = node.children[i]
        sibling = node.children[i + 1]

        child.keys.append(node.keys[i])
        child.keys.extend(sibling.keys)
        if not child.leaf:
            child.children.extend(sibling.children)

        node.keys.pop(i)
        node.children.pop(i + 1)

    # ── Range Query ─────────────────────────────────────────────────

    def range_query(self, lo, hi) -> list:
        """Return all keys k with lo <= k <= hi."""
        result = []
        self._range_query(self.root, lo, hi, result)
        return result

    def _range_query(self, node: BTreeNode, lo, hi, result: list):
        i = 0
        while i < len(node.keys):
            # Recurse into left child if needed
            if not node.leaf and node.keys[i] >= lo:
                self._range_query(node.children[i], lo, hi, result)
            if lo <= node.keys[i] <= hi:
                result.append(node.keys[i])
            if node.keys[i] > hi:
                break
            i += 1
        # Trailing child
        if not node.leaf and (not node.keys or node.keys[-1] <= hi):
            self._range_query(node.children[i], lo, hi, result)

    # ── Utility ─────────────────────────────────────────────────────

    def inorder(self) -> list:
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node: BTreeNode, result: list):
        for i, key in enumerate(node.keys):
            if not node.leaf:
                self._inorder(node.children[i], result)
            result.append(key)
        if not node.leaf:
            self._inorder(node.children[-1], result)

    def __repr__(self):
        return f"BTree(t={self.t}, keys={self.inorder()})"


# ── Quick demo ─────────────────────────────────────────────────────

if __name__ == "__main__":
    tree = BTree(t=3)
    values = [10, 20, 5, 6, 12, 30, 7, 17, 3, 1, 25, 40, 50, 35]

    for v in values:
        tree.insert(v)

    print("Inorder:", tree.inorder())

    node, idx = tree.search(12)
    print(f"Search 12: found={node is not None}, keys_at_node={node.keys if node else None}")

    node, idx = tree.search(99)
    print(f"Search 99: found={node is not None}")

    print(f"Range [10, 30]: {tree.range_query(10, 30)}")

    for v in [6, 17, 40]:
        tree.delete(v)
        print(f"Deleted {v}: {tree.inorder()}")

    print(f"Range [5, 25] after deletes: {tree.range_query(5, 25)}")
